  gap: 0.5rem;
  font-size: 0.875rem;
  color: rgba(255,255,255,0.85);
}

.featured-card .featured-avatar {
  width: 28px;
  height: 28px;
  border-radius: 50%;
  object-fit: cover;
  border: 2px solid rgba(255,255,255,0.5);
}

/* Section headings */
.section-title {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--text);
  margin-bottom: 1.5rem;
  letter-spacing: -0.02em;
}

/* Buttons */
.btn {
  display: inline-flex;
  align-items: center;
  justify-content: center;
  padding: 0.625rem 1.5rem;
  border-radius: var(--radius);
  font-weight: 600;
  font-size: 0.875rem;
  font-family: var(--font-sans);
  cursor: pointer;
  transition: all 150ms ease;
  border: none;
  text-decoration: none;
}

.btn-primary {
  background: var(--accent);
  color: var(--primary);
}

.btn-primary:hover {
  background: var(--accent-hover);
  color: var(--primary);
}

.btn-outline {
  background: transparent;
  border: 2px solid var(--border);
  color: var(--text);
}

.btn-outline:hover {
  border-color: var(--primary);
  color: var(--primary);
}

.btn-lg {
  padding: 0.875rem 2rem;
  font-size: 1rem;
}

/* Footer */
.site-footer {
  background: var(--primary);
  color: rgba(255,255,255,0.7);
  padding: 3rem 0 2rem;
  margin-top: 4rem;
}

.footer-mission {
  font-size: 0.875rem;
  line-height: 1.7;
  max-width: 640px;
  margin-bottom: 2rem;
  color: rgba(255,255,255,0.6);
}

.footer-heading {
  font-size: 0.75rem;
  font-weight: 700;
  text-transform: uppercase;
  letter-spacing: 0.08em;
  color: rgba(255,255,255,0.4);
  margin-bottom: 1rem;
}

.footer-trending {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.footer-trending a {
  font-size: 0.8125rem;
  color: var(--accent);
  padding: 0.25rem 0;
}

.footer-trending a:hover {
  color: #fff;
}

.footer-links {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem 1.5rem;
  margin-bottom: 2rem;
}

.footer-links a {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.6);
}

.footer-links a:hover {
  color: #fff;
}

.footer-bottom {
  border-top: 1px solid rgba(255,255,255,0.08);
  padding-top: 1.5rem;
  font-size: 0.75rem;
  color: rgba(255,255,255,0.3);
}

/* Donation page */
.donation-hero {
  background: var(--primary);
  color: #fff;
  padding: 4rem 0;
  text-align: center;
}

.donation-hero h1 {
  font-size: 2.25rem;
  font-weight: 800;
  margin-bottom: 1rem;
  letter-spacing: -0.02em;
}

.donation-hero p {
  font-size: 1.0625rem;
  color: rgba(255,255,255,0.7);
  max-width: 640px;
  margin: 0 auto;
  line-height: 1.7;
}

.amount-tabs {
  display: flex;
  gap: 0.5rem;
  justify-content: center;
  margin: 2rem 0 1rem;
}

.amount-tab {
  padding: 0.75rem 1.75rem;
  border-radius: var(--radius);
  font-weight: 700;
  font-size: 1.125rem;
  background: rgba(255,255,255,0.1);
  color: rgba(255,255,255,0.7);
  border: 2px solid transparent;
  cursor: pointer;
  transition: all 150ms ease;
  font-family: var(--font-sans);
}

.amount-tab:hover {
  background: rgba(255,255,255,0.15);
  color: #fff;
}

.amount-tab.active {
  background: var(--accent);
  color: var(--primary);
  border-color: var(--accent);
}

.donation-desc {
  font-size: 1rem;
  color: rgba(255,255,255,0.85);
  margin-bottom: 1.5rem;
  min-height: 1.5em;
}

.donate-btn {
  background: var(--accent);
  color: var(--primary);
  font-weight: 700;
  font-size: 1.125rem;
  padding: 0.875rem 3rem;
  border-radius: var(--radius);
  border: none;
  cursor: pointer;
  transition: all 150ms ease;
  font-family: var(--font-sans);
}

.donate-btn:hover {
  background: var(--accent-hover);
}

.donate-sublabel {
  font-size: 0.8125rem;
  color: rgba(255,255,255,0.5);
  margin-top: 0.75rem;
}

/* Accordion */
.accordion-item {
  border-bottom: 1px solid var(--border);
}

.accordion-header {
  display: flex;
  align-items: center;
  justify-content: space-between;
  padding: 1rem 0;
  cursor: pointer;
  font-weight: 600;
  font-size: 0.9375rem;
  color: var(--text);
  transition: color 150ms ease;
  background: none;
  border: none;
  width: 100%;
  text-align: left;
  font-family: var(--font-sans);
}

.accordion-header:hover {
  color: var(--link);
}

.accordion-icon {
  transition: transform 200ms ease;
  flex-shrink: 0;
  margin-left: 1rem;
}

.accordion-item.active .accordion-icon {
  transform: rotate(180deg);
}

.accordion-content {
  max-height: 0;
  overflow: hidden;
  transition: max-height 300ms ease;
}

.accordion-item.active .accordion-content {
  max-height: 500px;
}

.accordion-body {
  padding: 0 0 1rem;
  font-size: 0.875rem;
  color: var(--text-secondary);
  line-height: 1.7;
}

/* Popular tags */
.popular-tags-row {
  display: flex;
  flex-wrap: wrap;
  gap: 0.5rem;
  margin-bottom: 2rem;
}

.popular-tag-item {
  display: flex;
  align-items: center;
  gap: 0.375rem;
  font-size: 0.8125rem;
  font-weight: 500;
  color: var(--text-secondary);
  padding: 0.375rem 0.875rem;
  background: var(--bg-light);
  border-radius: 9999px;
  border: 1px solid var(--border);
  transition: all 150ms ease;
  text-decoration: none;
}

.popular-tag-item:hover {
  border-color: var(--accent);
  color: var(--text);
}

.popular-tag-item .tag-count {
  font-size: 0.75rem;
  color: var(--text-muted);
}

/* Tag header */
.tag-header-section {
  padding: 2rem 0;
}

.tag-header-section h1 {
  font-size: 2rem;
  font-weight: 800;
  letter-spacing: -0.02em;
}

.tag-header-section .tag-subtitle {
  font-size: 1rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

/* Learn page */
.learn-hero {
  background: var(--primary);
  color: #fff;
  padding: 3rem 0;
  text-align: center;
}

.learn-hero h1 {
  font-size: 2rem;
  font-weight: 800;
  margin-bottom: 0.5rem;
}

.learn-hero p {
  color: rgba(255,255,255,0.7);
  font-size: 1rem;
}

.cert-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(320px, 1fr));
  gap: 1rem;
}

.cert-card {
  display: flex;
  align-items: center;
  gap: 1rem;
  padding: 1.25rem;
  background: var(--bg-card);
  border: 1px solid var(--border);
  border-radius: var(--radius-lg);
  transition: all 200ms ease;
  cursor: pointer;
  text-decoration: none;
  color: var(--text);
}

.cert-card:hover {
  border-color: var(--accent);
  box-shadow: var(--shadow-md);
  transform: translateY(-1px);
  color: var(--text);
}

.cert-icon {
  width: 48px;
  height: 48px;
  border-radius: var(--radius);
  display: flex;
  align-items: center;
  justify-content: center;
  flex-shrink: 0;
  background: var(--bg-light);
  color: var(--primary);
}

.cert-card-title {
  font-weight: 600;
  font-size: 0.9375rem;
}

/* Daily challenge */
.challenge-card {
  background: linear-gradient(135deg, var(--primary) 0%, #1b1b3a 100%);
  color: #fff;
  border-radius: var(--radius-lg);
  padding: 2rem;
  margin: 2rem 0;
}

.challenge-card h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.challenge-links {
  display: flex;
  gap: 1rem;
  flex-wrap: wrap;
}

.challenge-links a {
  color: var(--accent);
  font-weight: 600;
  font-size: 0.9375rem;
}

.challenge-links a:hover {
  color: #fff;
}

/* Supporter benefits */
.benefits-list {
  list-style: none;
  padding: 0;
}

.benefits-list li {
  padding: 0.75rem 0;
  padding-left: 1.75rem;
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
}

.benefits-list li:last-child {
  border-bottom: none;
}

.benefits-list li::before {
  content: '✓';
  position: absolute;
  left: 0;
  color: #059669;
  font-weight: 700;
}

/* Initiative list */
.initiative-list {
  list-style: none;
  padding: 0;
}

.initiative-list li {
  padding: 0.75rem 0;
  padding-left: 1.75rem;
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
}

.initiative-list li:last-child {
  border-bottom: none;
}

.initiative-list li::before {
  content: '→';
  position: absolute;
  left: 0;
  color: var(--accent);
  font-weight: 700;
}

/* Achievement stats */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}

.stat-item {
  padding: 1.25rem;
  background: var(--bg-light);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--accent);
}

.stat-item .stat-number {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.stat-item .stat-label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

/* Load more */
.load-more-wrap {
  text-align: center;
  margin-top: 2rem;
  padding-bottom: 2rem;
}

/* Animation */
@keyframes fadeIn {
  from { opacity: 0; transform: translateY(10px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in {
  animation: fadeIn 400ms ease-out;
}

/* Section spacing */
.section-spacing {
  padding: 3rem 0;
}

.section-spacing + .section-spacing {
  padding-top: 0;
}
