  margin: 2rem 0;
}

.challenge-card h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
}

.challenge-links {
  display: flex;
  gap: 1.5rem;
  flex-wrap: wrap;
}

.challenge-links a {
  color: var(--accent);
  font-weight: 600;
  font-size: 0.9375rem;
}

.challenge-links a:hover { color: #fff; }

