.learn-subsection h2 {
  font-size: 1.25rem;
  font-weight: 700;
  margin-bottom: 1rem;
  color: var(--text);
}

.learn-link-list {
  display: flex;
  flex-direction: column;
  gap: 0.75rem;
}

.learn-link-list a {
  font-size: 0.9375rem;
  color: var(--link);
  font-weight: 500;
  display: flex;
  align-items: center;
  gap: 0.5rem;
}

.learn-link-list a:hover { color: var(--link-hover); }

.learn-link-list a svg {
  width: 16px;
  height: 16px;
  flex-shrink: 0;
}

/* ── Benefits list ── */
.benefits-list { list-style: none; }

.benefits-list li {
  padding: 0.75rem 0 0.75rem 1.75rem;
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
}

.benefits-list li:last-child { border-bottom: none; }

.benefits-list li::before {
  content: '\2713';
  position: absolute;
  left: 0;
  color: #059669;
  font-weight: 700;
}

/* ── Initiative list ── */
.initiative-list { list-style: none; }

.initiative-list li {
  padding: 0.75rem 0 0.75rem 1.75rem;
  position: relative;
  font-size: 0.9375rem;
  color: var(--text-secondary);
  border-bottom: 1px solid var(--border-light);
}

.initiative-list li:last-child { border-bottom: none; }

.initiative-list li::before {
  content: '\2192';
  position: absolute;
  left: 0;
  color: var(--accent);
  font-weight: 700;
}

/* ── Stats grid ── */
.stats-grid {
  display: grid;
  grid-template-columns: repeat(auto-fill, minmax(240px, 1fr));
  gap: 1rem;
}

.stat-item {
  padding: 1.25rem;
  background: var(--bg-light);
  border-radius: var(--radius-lg);
  border-left: 4px solid var(--accent);
}

.stat-item .stat-number {
  font-size: 1.5rem;
  font-weight: 800;
  color: var(--primary);
}

.stat-item .stat-label {
  font-size: 0.8125rem;
  color: var(--text-muted);
  margin-top: 0.25rem;
}

/* ── Load more ── */
.load-more-wrap {
  text-align: center;
  margin-top: 2.5rem;
  padding-bottom: 1rem;
}

/* ── Section spacing ── */
.section-spacing { padding: 3rem 0; }

/* ── Animation ── */
@keyframes fadeInUp {
  from { opacity: 0; transform: translateY(16px); }
  to { opacity: 1; transform: translateY(0); }
}

.fade-in-up { animation: fadeInUp 400ms ease-out both; }

.fade-in-up:nth-child(2) { animation-delay: 60ms; }
.fade-in-up:nth-child(3) { animation-delay: 120ms; }
.fade-in-up:nth-child(4) { animation-delay: 180ms; }
.fade-in-up:nth-child(5) { animation-delay: 240ms; }

/* ── Donation sections ── */
.donate-section {
  padding: 3rem 0;
  border-top: 1px solid var(--border-light);
}

.donate-section h2 {
  font-size: 1.375rem;
  font-weight: 700;
  margin-bottom: 1.25rem;
  color: var(--text);
}

